```javascript
// 创建和动画化圆圈的函数
function createMovingCircle() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("width", "100%");
  svg.setAttribute("height", "100%");
  document.body.appendChild(svg);

  const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
  circle.setAttribute("r", "20");
  circle.setAttribute("fill", "red");
  circle.style.position = "fixed";
  circle.style.filter = "blur(3px)";
  circle.style.transition = "transform 0.1s linear";
  svg.appendChild(circle);

  let x = Math.random() * (window.innerWidth - 40);
  let y = Math.random() * (window.innerHeight - 40);
  let dx = 200 / 1000;
  let dy = 200 / 1000;

  const moveCircle = () => {
    x += dx;
    y += dy;

    if (x < 0 || x > window.innerWidth - 40) {
      dx = -dx;
    }
    if (y < 0 || y > window.innerHeight - 40) {
      dy = -dy;
    }

    circle.style.transform = `translate(${x}px, ${y}px)`;

    requestAnimationFrame(moveCircle);
  };

  moveCircle();
}

// 创建移动圆圈
createMovingCircle();
```

