假设纠错码（ECC）是一个汉明码，码率为1/2，并且每个数据字节需要一个ECC字节，那么在单个千兆字节的数字存储空间中最多可以保存多少个二进制位：
包 main
import (
	"fmt"
)
func main() {
	// 1千兆字节 = 1,073,741,824字节
	// 1字节 = 8位
	// 1千兆字节 = 8,589,934,592位
	// 每个数据字节需要一个ECC字节
	// ECC码率 = 1/2
	// 数据字节的数量 = (1/2) * ECC字节的数量
	// 位数 = 8 * (数据字节的数量 + ECC字节的数量)
	numBits := 8589934592.0 // 1千兆字节 = 8,589,934,592位
	numECCBytes := numBits / 16.0
	numDataBytes := numECCBytes / 2.0
	numTotalBytes := numDataBytes + numECCBytes
	fmt.Printf("在具有纠错能力的单个千兆字节的数字存储空间中可以保存的最大二进制位数为%.0f。\n", numTotalBytes*8)
}

