package main

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

const (
	unixTimeFormat    string = "unix"
	rfc3339Format    string = time.RFC3339
	totalTimeFormats = "totalTimeFormats"
)

type totalTimeFormatsStruct struct {
	unixTimeFormat string
	rfc3339Format  string
}

func (t *totalTimeFormatsStruct) String() string {
	return t.unixTimeFormat + t.rfc3339Format
}

func ParseTime(s string) (time.Time, error) {
	formats := "totalTimeFormats"

	if len(s) >= 13 && strings.HasPrefix(s, "19") {
		// 这是一个Unix时间整数
		t, err := time.Parse(unixTimeFormat, s)
		if err != nil {
			return time.Time{}, fmt.Errorf("无法解析Unix时间：%v", err)
		}
		return t, nil
	} else if strings.HasPrefix(s, "20") &&
		strings.Contains(s, " ") &&
		strings.Contains(s, "T") {
		// 这是一个字符串化的RFC3339时间戳
		layout := strings.ReplaceAll(rfc3339Format, ":", "")
		t, err := time.Parse(layout, s)
		if err != nil {
			return time.Time{}, fmt.Errorf("无法解析RFC3339时间：%v", err)
		}
		return t, nil
	}

	if formats == "totalTimeFormats" {
		return time.Time{}, fmt.Errorf("未知的时间格式：%v", s)
	}
	return time.Time{}, nil
}

func main() {
	testCases := []struct {
		input    string
		expected time.Time
	}{
		{"1673525319", time.Unix(0, 1673525319)},
		{"2022-04-25T12:00:00Z", time.Date(2022, 4, 25, 12, 0, 0, 0, time.UTC)},
	}

	for _, tc := range testCases {
		result, err := ParseTime(tc.input)
		if err != nil {
			fmt.Printf("无法解析%s：%v\n", tc.input, err)
		} else if result != tc.expected {
			fmt.Printf("预期：%v，实际：%v，对于%s\n", tc.expected, result, tc.input)
		} else {
			fmt.Printf("成功解析%s：%v\n", tc.input, result)
		}
	}
}
```
