// 用于检查文件存在性和创建目录的函数
static int check_exists(const char *path) {
    struct stat buf;
    return (stat(path, &buf) == 0);
}

static void makedir(const char *path) {
    if (!check_exists(path)) {
        mkdir(path, 0744);
    }
}

// 添加文件到zip归档文件的辅助函数
static void add_file_to_zip(const char * filename, const char *arcname, zipFile z) {
    FILE * input_file = fopen(filename, "r");
    if (!input_file) {
        fprintf(stderr, "无法打开文件：%s\n", filename);
        return;
    }

    char buf[1024];
    int len;
    while ((len = fread(buf, 1, sizeof(buf), input_file)) > 0) {
        int ret = zipWriteInFileInZip(z, buf, len);
        if (ret < 0) {
            fprintf(stderr, " 无法将文件写入归档文件\n");
            break;
        }
    }
    fclose(input_file);

    // 如果需要，在zip归档文件中创建目录
    char dir[1024];
    const char *last_slash = rindex(arcname, '/');
    if (last_slash != NULL) {
        memcpy(dir, arcname, last_slash - arcname);
        dir[last_slash - arcname] = '\0';
        makedir(dir, 0744);
    }
}

int main() {
    // 创建一个zip归档文件
    zipFile z = zipOpen("output.zip", 0, NULL);
    if (z == NULL) {
        fprintf(stderr, "无法创建zip文件\n");
        return -1;
    }

    // 将文件添加到zip归档文件
    const char *files[] = {"file1.txt", "file2.txt", "folder/file3.txt"};
    for (int i = 0; i < sizeof(files) / sizeof(files[0]); i++) {
        add_file_to_zip(files[i], files[i], z);
    }

    // 结束zip归档文件
    zipClose(z, 0);

    return 0;
}
```
