import com.google.protobuf.InvalidProtocolBufferException;
import your.package.generated.MessageAOuterClass.MessageA;
import your.package.generated.MessageBOuterClass.MessageB;

public class ProtoDeserializer {

    public static void main(String[] args) {
        byte[] byteArray = ...; // The protobuf encoded byte array

        Object deserializedMessage = deserialize(byteArray, MessageA.parser(), MessageB.parser());
        if (deserializedMessage instanceof MessageA) {
            System.out.println("Deserialized into MessageA: " + deserializedMessage);
        } else if (deserializedMessage instanceof MessageB) {
