    private static <T> T deserialize(byte[] byteArray, MessageA.Parser<T>... parsers) {
        for (MessageA.Parser<T> parser : parsers) {
            try {
                return parser.parseFrom(byteArray);
            } catch (InvalidProtocolBufferException e) {
                // Ignore exceptions and try the next parser
            }
        }
        return null;
    }
}
