以下是数据库的示例架构：
CREATE TABLE coffee (
    id INT PRIMARY KEY AUTO_INCREMENT,
    name VARCHAR(255) NOT NULL,
    origin VARCHAR(255) NOT NULL,
    roast_level VARCHAR(255) NOT NULL,
    flavor_notes TEXT NOT NULL,
    date_added TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

添加新咖啡豆到数据库中的PHP示例：
<?php
    $conn = new mysqli($servername, $username, $password, $dbname);

    // 检查连接
    if ($conn->connect_error) {
        die("连接失败: " . $conn->connect_error);
    } 

    // 准备和绑定
    $stmt = $conn->prepare("INSERT INTO coffee (name, origin, roast_level, flavor_notes) VALUES (?, ?, ?, ?)");
    $stmt->bind_param("ssss", $name, $origin, $roast_level, $flavor_notes);

    // 设置参数并执行
    $name = "示例咖啡";
    $origin = "哥伦比亚";
    $roast_level = "中度";
    $flavor_notes = "带有巧克力和肉豆蔻的味道";
    $stmt->execute();

    echo "新记录创建成功";

    $stmt->close();
    $conn->close();
?>

