```php
<?php
function analyze_sentiment($text) {
  $tokens = token_get_all($text);
  $sentences = array_map('str_split', $tokens);
  $sentiments = array_map('sentiment_analysis', $sentences);
  return array_average($sentiments);
}

function sentiment_analysis($sentence) {
  $sentence = strtolower($sentence);
  $sentence = preg_replace('/[^a-z]+/', ' ', $sentence);
  $sentence = explode(' ', $sentence);

  $sentiment = 0;
  foreach ($sentence as $word) {
    if (isset($word_sentiments[$word])) {
      $sentiment += $word_sentiments[$word];
    }
  }
  return $sentiment;
}

$word_sentiments = [
  'love' => 1,
  'wisdom' => 1,
  'chill' => -1,
  // 添加更多单词及其情感值
];
?>
```

